{"cards": [{"node_code": "N_a570845e55f87dce", "definition": "研究铁路线路工程中应用的有机高分子材料及化工合成材料，涵盖塑料、橡胶、合成树脂、沥青改性剂及各类化工助剂的性能、加工与工程应用。", "boundary": "本节点聚焦于“有机”与“化工”属性的材料。边界在于区分“有机/化工材料”与“非金属材料”（如天然石材、普通混凝土、道砟归入非金属材料）、“粘结料”（若为专用粘结剂，视具体成分归入粘结料或本节点，通常通用粘结剂归粘结料，化工合成树脂类归本节点）。若涉及纯化学合成反应机理而非工程应用，不作主挂载。", "includes": ["铁路用塑料、橡胶、合成树脂及复合材料", "沥青及其改性剂、乳化沥青等化工处理材料", "线路工程中使用的各类化工助剂、添加剂及防腐涂料基底"], "excludes": ["天然无机非金属材料（如道砟、水泥、砂石，归入非金属材料）", "专用结构粘结剂（若树中有独立粘结料节点，优先归入粘结料）", "纯基础有机化学理论（非工程应用导向）"], "sibling_distinctions": [{"other_code": "N_4ae316405c65d7ff", "rule": "区分依据为材料属性：本节点关注有机高分子及化工合成材料；非金属材料关注无机非金属（如混凝土、石材、道砟）。"}, {"other_code": "N_7244e7e7625f89f0", "rule": "区分依据为功能侧重：本节点关注材料本身的化学组成与性能；粘结料关注具有特定粘结功能的材料体系，若为通用化工粘结剂可交叉，但专用结构胶归粘结料。"}], "cross_boundary_rule": "若内容涉及“沥青混凝土”，若侧重沥青（有机/化工）性能，主挂载本节点；若侧重混凝土整体结构性能，可关联非金属材料，但沥青组分归本节点。"}, {"node_code": "N_8c004cba88b0b49c", "definition": "研究铁路线路工程中使用的金属材料，包括钢轨、扣件、道钉、路基金属构件、桥梁支座金属件及各类金属防腐与连接材料。", "boundary": "本节点聚焦于“金属”属性的材料。边界在于区分“金属材料”与“非金属材料”（如混凝土、道砟）、“有机材料”（如塑料、橡胶）。若涉及金属材料的冶炼基础理论，不作主挂载；若涉及金属在铁路线路中的具体选材、性能要求及防腐处理，归入本节点。", "includes": ["钢轨、鱼尾板、扣件、道钉等轨道用金属材料", "路基、桥涵、隧道工程中使用的钢材、铝合金及金属构件材料", "金属防腐、防锈、耐磨涂层及金属连接材料"], "excludes": ["非金属材料（如混凝土、沥青、道砟，归入非金属材料）", "有机高分子材料（如塑料、橡胶，归入有机材料、化工材料）", "纯冶金工艺与基础金属学理论（非铁路工程应用导向）"], "sibling_distinctions": [{"other_code": "N_4ae316405c65d7ff", "rule": "区分依据为材料属性：本节点关注金属元素及其合金；非金属材料关注无机非金属及天然矿物材料。"}, {"other_code": "N_a570845e55f87dce", "rule": "区分依据为材料属性：本节点关注金属；有机材料关注碳基高分子及化工合成物。"}], "cross_boundary_rule": "若内容涉及“金属-非金属复合材料”（如钢纤维混凝土），若侧重金属增强相，可关联本节点；若侧重混凝土基体，主挂载非金属材料。"}, {"node_code": "N_c495151767b6dd42", "definition": "研究铁路线路工程中使用的、未归入金属、非金属、有机化工及特定功能类别的其他特种工程材料，涵盖新型复合材料、智能材料及特殊环境适应性材料。", "boundary": "本节点为“兜底”节点，用于容纳无法明确归入其他兄弟节点的特种材料。边界在于优先检查是否属于金属、非金属、有机化工或特定功能（防水、防火、隔热等）材料，若符合则归入对应节点；仅当材料具有跨类别特性或属于新兴特种材料时，归入本节点。", "includes": ["新型复合材料（如碳纤维增强复合材料在铁路中的特殊应用）", "智能材料（如自感知、自修复材料在铁路线路中的应用）", "特殊环境（如高寒、高盐雾、强辐射）下的特种防护材料"], "excludes": ["已明确归入金属、非金属、有机化工或特定功能类别的材料", "通用建筑材料（若已有明确归属，不在此处重复）", "纯基础材料科学理论（非铁路工程应用导向）"], "sibling_distinctions": [{"other_code": "N_4ae316405c65d7ff", "rule": "区分依据为材料分类明确性：非金属材料涵盖常规无机非金属；本节点涵盖非常规、跨类别或新型特种材料。"}, {"other_code": "N_a570845e55f87dce", "rule": "区分依据为材料分类明确性：有机化工材料涵盖常规高分子及化工品；本节点涵盖非常规、跨类别或新型特种材料。"}], "cross_boundary_rule": "若内容涉及“多功能复合特种材料”，若主要功能可明确归入防水、防火等特定功能节点，主挂载该功能节点；若功能复合且无单一主导，或属于新型材料体系，主挂载本节点。"}]}
